-- =====================================================================================
-- Reformulação regulatória 2026-09-16 — Melatonina + Triptofanos (Encapsulados) (melatonina-triptofanos-encapsulados)
-- Fragmento PL/pgSQL idempotente, casando por SLUG (nunca UUID), no estilo de
-- supabase/migrations/20260920000000_composicoes_conforme_rotulo.sql.
-- Fonte: docs/conformidade/reformulacao/melatonina-triptofanos-encapsulados.md e scratchpad/fase2/melatonina-triptofanos-encapsulados.json.
-- Sem guarda de contagem aqui (a consolidação põe); só o bloco deste produto.
-- NÃO APLICADO em nenhum banco. Veredito esperado: CONFORME CONDICIONADO A (laudo vigente de melatonina; laudo novo de bisglicinato de magnésio; laudo de ácido L-aspártico ou sua retirada; laudo de L-triptofano do lote a usar; emissão do memorial de cálculo pelo RT)
-- =====================================================================================

-- 1. exclusão lógica das composições ativas atuais desta fórmula
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null and f.slug = 'melatonina-triptofanos-encapsulados'
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

-- 2. inserção das composições reformuladas (ingredient_id resolvido por slug; só se ainda não houver linha desta fonte)
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata)
select f.id, v.ingredient_name, v.quantity, v.unit::public.composition_unit, v.sort_order, i.id, v.metadata::jsonb
from (values
    ('melatonina-triptofanos-encapsulados', 0, 'L-triptofano', 500, 'mg', 'l-triptofano', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Triptofano", "forma_insumo": "L-Triptofano (CAS 73-22-3)", "massa_insumo_mg": 500.5005, "laudo_lote": "950388 (Analitic, fabricante SA20241004046X)", "laudo_validade": "03/10/2026", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 500, "unidade_ativo": "mg", "minimo": 42, "maximo": 860, "pct_do_maximo": 58.14, "linha_anexo": "I·L-Triptofano; III·Triptofano 42 mg; IV·860 mg", "status": "dose ajustada", "e_sal": false, "observacao": "572,38 mg (66,6% do teto) → 500 mg (58,1% do teto): libera 72 mg para o magnésio chegar ao mínimo com folga. Sem laudo no cadastro (dossiê gerado); usado o laudo do lote 950388 do memorial DREAM-GUMMY — pedir laudo novo antes de pesar (validade em 03/10/2026)."}'),
    ('melatonina-triptofanos-encapsulados', 1, 'Ácido L-aspártico', 100, 'mg', 'acido-l-aspartico', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Aspartato", "forma_insumo": "Ácido L-aspártico (CAS 56-84-8) — insumo sem laudo na máquina", "massa_insumo_mg": 100.0, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 100.0, "teor_fonte": "assumido", "ativo_mg": 100, "unidade_ativo": "mg", "minimo": null, "maximo": 5320, "pct_do_maximo": 1.88, "linha_anexo": "I·Ácido L-aspártico; III·Aspartato NE; IV·5.320 mg", "status": "dose ajustada — PENDENTE laudo", "e_sal": false, "observacao": "150 mg (2,8% do teto) → 100 mg (1,9%): libera 50 mg. O cadastro é a única fonte da dose; sem laudo, sem lote. Comprar/obter laudo ou retirar (não há mínimo)."}'),
    ('melatonina-triptofanos-encapsulados', 2, 'L-glutamina', 95, 'mg', 'l-glutamina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Glutamina", "forma_insumo": "L-Glutamina (CAS 56-85-9)", "massa_insumo_mg": 96.4728, "laudo_lote": "AUTO039665 (Lepuge, fabricante GM2411016)", "laudo_validade": "08/11/2026", "laudo_vencido": false, "teor_pct": 98.47, "teor_fonte": "laudo", "ativo_mg": 95, "unidade_ativo": "mg", "minimo": null, "maximo": 5000, "pct_do_maximo": 1.9, "linha_anexo": "I·L-Glutamina; III·Glutamina NE; IV·5.000 mg", "status": "mantido (dose arredondada)", "e_sal": false, "observacao": "94,77 mg (1,9% do teto) → 95 mg. O cadastro não tem lote; o laudo Lepuge AUTO039665 é o único válido em texto (vence em 7 semanas)."}'),
    ('melatonina-triptofanos-encapsulados', 3, 'Magnésio (bisglicinato de magnésio)', 70, 'mg', 'magnesio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Magnésio", "forma_insumo": "Bisglicinato de magnésio (CAS 14783-68-7)", "massa_insumo_mg": 231.6347, "laudo_lote": "90844 (Analitic, fabricante 66342023062230)", "laudo_validade": "21/06/2025", "laudo_vencido": true, "teor_pct": 30.22, "teor_fonte": "laudo vencido", "ativo_mg": 70, "unidade_ativo": "mg", "minimo": 63, "maximo": 350, "pct_do_maximo": 20.0, "linha_anexo": "I·Bisglicinato de magnésio; III/IV·Magnésio", "status": "dose ajustada — PENDENTE laudo", "e_sal": false, "observacao": "63 mg era o mínimo exato (e, se os 63 mg do cadastro fossem massa de sal, 19,1 mg de Mg); 70 mg = 111% do mínimo (20% do teto). Massa de sal 231,63 mg — a maior mudança de massa da fórmula. Laudo novo obrigatório; alternativa: óxido de magnésio (116,08 mg)."}'),
    ('melatonina-triptofanos-encapsulados', 4, 'Zinco (bisglicinato de zinco)', 10, 'mg', 'zinco', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Zinco", "forma_insumo": "Bisglicinato de zinco (CAS 14281-83-5)", "massa_insumo_mg": 50.2765, "laudo_lote": "055-ZN/25 (Galena, CIQ 2505027507)", "laudo_validade": "06/05/2027", "laudo_vencido": false, "teor_pct": 19.89, "teor_fonte": "laudo", "ativo_mg": 10, "unidade_ativo": "mg", "minimo": 1.65, "maximo": 29.59, "pct_do_maximo": 33.8, "linha_anexo": "I·Bisglicinato de zinco; III/IV·Zinco", "status": "dose ajustada", "e_sal": false, "observacao": "29,59 mg era o teto exato (e exigiria 148,8 mg de sal); nova dose 10 mg (33,8% do teto; 91% do VD) — dose típica dos outros produtos da linha."}'),
    ('melatonina-triptofanos-encapsulados', 5, 'Melatonina', 0.18, 'mg', 'melatonina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Melatonina", "forma_insumo": "Melatonina (CAS 73-31-4)", "massa_insumo_mg": 0.1812, "laudo_lote": "950151 (Analitic, fabricante MCS211210) — os 5 laudos de melatonina da máquina estão vencidos", "laudo_validade": "09/12/2024", "laudo_vencido": true, "teor_pct": 99.33, "teor_fonte": "laudo vencido", "ativo_mg": 0.18, "unidade_ativo": "mg", "minimo": null, "maximo": 0.21, "pct_do_maximo": 85.71, "linha_anexo": "I·Melatonina (IN 102/2021); III·NE; IV·0,21 mg", "status": "dose ajustada — PENDENTE laudo", "e_sal": false, "observacao": "0,21 mg era o teto exato; nova dose 0,18 mg (85,7% do teto). Os cinco laudos de melatonina da máquina estão vencidos — laudo do lote em uso é obrigatório (ultrapassar 0,21 mg é infração de segurança)."}'),
    ('melatonina-triptofanos-encapsulados', 6, 'Biotina (D-biotina)', 40, 'mcg', 'biotina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Biotina", "forma_insumo": "D-biotina (CAS 58-85-5)", "massa_insumo_mg": 0.04, "laudo_lote": "91457 (Analitic, fabricante BN25121020; o arquivo está nomeado com o lote 25030042)", "laudo_validade": "19/12/2028", "laudo_vencido": false, "teor_pct": 100.0, "teor_fonte": "laudo", "ativo_mg": 0.04, "unidade_ativo": "µg", "minimo": 4.5, "maximo": 45, "pct_do_maximo": 88.89, "linha_anexo": "I·D-biotina; III/IV·Biotina", "status": "dose ajustada", "e_sal": false, "observacao": "45 µg era o teto exato; nova dose 40 µg (88,9%; 133% do VD)."}'),
    ('melatonina-triptofanos-encapsulados', 7, 'Dióxido de silício (INS 551)', 20.894, 'mg', 'dioxido-de-silicio', '{"fonte": "reformulacao_2026-09-16", "excipiente": true, "ins": "551", "observacao": "q.s.p. 1.000 mg — quantum satis (IN 211/2023, 14.2). Folga de 2,1%, no limite mínimo de 2%: qualquer aumento de massa (ex.: teor menor do magnésio no laudo novo) exige recompor."}')
) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

